    pub fn find(&self, text: &str) -> Option<(TokenKind, usize)> {
        // Implement the logic to find the first match in the text and return the associated TokenKind and index
    }
}

pub struct TokenMatcher {
    rules: Vec<Rule>,
}

impl TokenMatcher {
    pub fn is_match(&self, text: &str) -> bool {
        self.rules.iter().any(|r| r.is_match(text))
    }

    pub fn find(&self, text: &str) -> Option<(TokenKind, usize)> {
        // max returns the last max so we reverse iteration to get the first max.
        self.rules
            .iter()
            .rev()
            .filter_map(|r| r.find(text))
            .max_by(|a, b| a.1.cmp(&b.1))
    }
}
```

